package authorization.ownership

import sttp.model.StatusCode
import java.util.Optional
import org.pac4j.core.client.Clients
import org.pac4j.core.config.Config
import org.pac4j.core.context.CallContext
import org.pac4j.core.credentials.{Credentials, UsernamePasswordCredentials}
import org.pac4j.core.credentials.authenticator.Authenticator
import org.pac4j.core.profile.CommonProfile
import org.pac4j.http.client.direct.DirectBasicAuthClient
import ba.sake.sharaf.*
import ba.sake.sharaf.pac4j.*
import ba.sake.sharaf.session.NoOpSessionStore
import ba.sake.sharaf.undertow.UndertowSharafServer

import ba.sake.tupson.JsonRW
import ba.sake.sharaf.exceptions.{NotFoundException, RejectedException}

case class CurrentUser(id: String)
case class Document(id: String, ownerId: String, title: String) derives JsonRW
case class Rename(title: String) derives JsonRW

class Documents:
  // In-memory demonstration state; reset whenever the server is recreated.
  private var documents = Map("private" -> Document("private", "alice", "Original"))

  def read(id: String)(using user: CurrentUser): Document = synchronized {
    documents.get(id).filter(_.ownerId == user.id)
      .getOrElse(throw NotFoundException("Document"))
  }

  def rename(id: String, title: String)(using CurrentUser): Document = synchronized {
    val updated = read(id).copy(title = title)
    documents = documents.updated(id, updated)
    updated
  }

  def delete(id: String)(using CurrentUser): Unit = synchronized {
    read(id)
    documents = documents.removed(id)
  }

object OwnershipExample:
  private val users = Map("alice" -> CurrentUser("alice"), "bob" -> CurrentUser("bob"))

  // Development credentials only: each listed username uses the password "demo".
  private def config(): Config =
    val authenticator = new Authenticator:
      override def validate(ctx: CallContext, credentials: Credentials): Optional[Credentials] =
        credentials match
          case c: UsernamePasswordCredentials
              if Set("alice", "bob", "unlinked").contains(c.getUsername) && c.getPassword == "demo" =>
            val profile = new CommonProfile()
            profile.setId(c.getUsername)
            c.setUserProfile(profile)
            Optional.of(c)
          case _ => Optional.empty()
    val client = new DirectBasicAuthClient(authenticator)
    client.setName("basic")
    new Config(new Clients(client))

  def authenticated(next: SharafHandler): SharafHandler =
    val security = Pac4jSecurityConfig(config(), clients = "basic", sessionStore = NoOpSessionStore())
    // Map application exceptions before pac4j can wrap them.
    Pac4jSecurityHandler(security, SharafHandler.exceptions(next, ExceptionMapper.json))

  def withCurrentUser[A](action: CurrentUser ?=> A): A =
    val user = SecurityService.currentUser.flatMap(profile => users.get(profile.getId))
      .getOrElse(throw RejectedException("No application account"))
    action(using user)

  def handler(): SharafHandler =
    val documents = new Documents()
    val routes = Routes {
      case GET -> Path("documents", id) => withCurrentUser {
        Response.withBody(documents.read(id))
      }
      case PUT -> Path("documents", id) => withCurrentUser {
        val change = Request.current.bodyJson[Rename]
        Response.withBody(documents.rename(id, change.title))
      }
      case DELETE -> Path("documents", id) => withCurrentUser {
        documents.delete(id)
        Response.withStatus(StatusCode.NoContent)
      }
    }
    SharafHandler.exceptions(authenticated(SharafHandler.routes(routes)), ExceptionMapper.json)

  def server(port: Int = 8181): UndertowSharafServer =
    UndertowSharafServer("localhost", port, handler())

  @main def runOwnership(): Unit =
    val app = server()
    sys.addShutdownHook(app.stop())
    app.start()
    println("Server started at http://localhost:8181")

Response Body Define a ResponseWritable[T] for your type. For example, to return XML: import java.io.OutputStream
import java.nio.charset.StandardCharsets
import ba.sake.sharaf.{HttpString, ResponseWritable}

case class MyXml(value: String)

given ResponseWritable[MyXml] with
  def write(value: MyXml, outputStream: OutputStream): Unit =
    outputStream.write(value.value.getBytes(StandardCharsets.UTF_8))

  def headers(value: MyXml): Seq[(HttpString, Seq[String])] =
    Seq(HttpString("Content-Type") -> Seq("application/xml; charset=utf-8"))
 Then return it from a route: Response.withBody(MyXml("<message>Hello</message>"))

Dependency Injection Do you even Dependency Injection?? Not in a classical / "dependency container" / Spring / JEE style. Not in a purely-functional-monadic style. Yes in a direct style: for singletons: just instantiate a class and pass the object around. for request/session-scoped instances: use scala 3 context functions (implicit functions). If you ever used PlayFramework, Slick 2 and similar, you might have used this pattern: someFunction { implicit ctx =>
    // some code that needs an implicit Ctx
}
 In Scala 3 there is a new concept called "context function" which represents the pattern from above with a type: type ContextualAction = Ctx ?=> Unit
 Now, instead of manually writing implicit ctx we can skip it: someFunction {
    // some code that needs an implicit Ctx
}
 and compiler will fill it in for us. The Ctx parameter is implicitly/contextually available (only) in the function body. You can get it with summon[Ctx] or using ctx: Ctx (which is a bit more readable). Sharaf has the Routes type that is defined as Request ?=> PartialFunction[RequestParams, Response[?]]. This means that you can call Request.current only in a Routes definition body (because it requires a given Request to be present). If you need a request-scoped instance (a-la @RequestScoped @Bean in Spring), you need to define a function that is using Request: def currentUser(using req: Request): User =
    // extract stuff from request
 Same as Request.current, you can only use the currentUser function in a context of a request! By using context functions, you avoid banging your head against the wall while trying to figure out how-the-hell can you inject a request-scoped-thing into a singleton/session-scoped thing... Proxy to proxy to proxy, something, something.. ok. You also avoid reading yet-another-lousy-monad-tutorial, losing your brain-battle agains State, RWS, Kleisli, higher-kinded-types, weird macros, compile times and type inference...

Routes Matching Routes matching design Web frameworks do their routes matching with various mechanisms: annotation + method param: Spring and most other popular Java frameworks, Cask etc special route file DSL: PlayFramework, Ruby on Rails in-language DSL: zio-http, akka-http pattern matching: Sharaf, http4s Why not annotations? Let's see an example: @GetMapping(value = "/student/{studentId}")
public Student studentData1(@PathVariable Integer studentId) {}

@GetMapping(value = "/student/{studentId}")
public Student studentData2(@PathVariable Integer studentId) {}

@GetMapping(value = "/student/umm")
public Student studentData3(@PathVariable Integer studentId) {}
 Issues: the studentId appears in 2 places, you can make a typo and nothing will work. the "/student/{studentId}" route is duplicated, there is no compiler support and it will fail only in runtime.. you have to wonder if studentData1 will be picked up before studentData3..!? Why not special route file? Well, you need a special compiler for this, essentially a new language. People have to learn how it works, there's probably no syntax highlighting, no autocomplete etc. Why not in-language DSL? Similar to special route file approach, people need to learn it. And again, you don't leverage compiler's support like exhaustive pattern matching and extractors. Sharaf's approach Sharaf does its route matching in plain scala code. Scala's pattern matching warns you when you have duplicate routes, or impossible routes. For example, if you write this: case GET -> Path("cars", brand) => ???
case GET -> Path("cars", model) => ??? // Unreachable case

case GET -> Path("files", segments*) => ???
case GET -> Path("files", "abc.txt") => ??? // Unreachable case
 you will get nice warnings, thanks compiler! You can extract path variables with pattern matching: case GET -> Path("cars", param[Int](carId)) => ???
 Here, the carId is parsed as Int and it mentioned only once, unlike with the annotation approach.

Tests Tests are essential to any serious software component. This example tests the server from the JSON API tutorial with MUnit and sttp client4. Create a file json_api.test.scala and paste this code into it: //> using scala 3.9.0
//> using dep ba.sake::tupson:0.18.0
//> using dep com.softwaremill.sttp.client4::core::4.0.13
//> using test.dep org.scalameta::munit::1.2.1

import sttp.client4.quick.*
import ba.sake.tupson.*

case class Car(brand: String, model: String, quantity: Int) derives JsonRW

class JsonApiSuite extends munit.FunSuite {

  val baseUrl = "http://localhost:8181"

  test("create and get cars") {
    locally {
      val res = quickRequest.get(uri"${baseUrl}/cars").send()
      val resBody = res.body.parseJson[Seq[Car]]
      assertEquals(res.code.code, 200)
      assertEquals(res.headers("content-type"), Seq("application/json; charset=utf-8"))
      assertEquals(resBody, Seq.empty)
    }

    locally {
      val body = Car("Mercedes", "ML350", 1)
      val res = quickRequest.post(uri"$baseUrl/cars").body(body.toJson).send()
      assertEquals(res.code.code, 200)
    }

    locally {
      val res = quickRequest.get(uri"$baseUrl/cars/Mercedes").send()
      val resBody = res.body.parseJson[Seq[Car]]
      assertEquals(res.code.code, 200)
      assertEquals(res.headers("content-type"), Seq("application/json; charset=utf-8"))
      assertEquals(resBody, Seq(Car("Mercedes", "ML350", 1)))
    }
  }
}

 First run the API server in one shell: scala json_api.sc
 and then run the tests in another shell: scala test json_api.test.scala
